/* category page banner margin */
.sc_layouts_item.elementor-element.elementor-element-41b88b28.sc_fly_static.elementor-widget.elementor-widget-trx_sc_layouts_title.trx_addons_parallax_layers_inited.trx_addons_parallax_blocks_inited {
    margin-bottom: 60px !Importantabove;
}
/* contact form btn */
span.submit-style-in {
    border-radius: 10px !important;
}
/* comment btn */
.show_comments_single {
    display: none !important;
}
/* footer menu */
@media (max-width: 767px) {

aside.widget.widget_custom_links .custom_links_list {
    all: unset;
    display: flex !important;
    flex-direction: column !important;
    align-items: center !important;
}
}

wp:postmeta.wp:meta_value:
a:2:{s:10:"hide_title";s:3:"yes";s:10:"custom_css";s:4941:"
@import url('https://fonts.googleapis.com/css2?family=Bebas+Neue&family=Oswald:wght@400;500;600;700&family=Montserrat:wght@300;400;500;600&display=swap');
:root{--jet:#0B0B0B;--red:#C1121F;--steel:#2B2B2B;--white:#F5F5F5;--gold:#C6A15B;}
.elementor-button{clip-path:polygon(8px 0%,100% 0%,calc(100% - 8px) 100%,0% 100%)!important;transition:all .25s!important;}
.elementor-button:hover{transform:translateY(-2px)!important;}
.fn-eyebrow{font-family:'Oswald',sans-serif;font-size:11px;letter-spacing:.22em;text-transform:uppercase;color:#C6A15B;}
.fn-tag{display:inline-flex;align-items:center;gap:10px;background:rgba(193,18,31,.12);border:1px solid rgba(193,18,31,.35);padding:8px 18px;font-family:'Oswald',sans-serif;font-size:11px;letter-spacing:.18em;text-transform:uppercase;color:#C6A15B;margin-bottom:28px;}
.fn-pill{display:inline-block;background:rgba(193,18,31,.1);border:1px solid rgba(193,18,31,.28);color:#C1121F;font-family:'Oswald',sans-serif;font-size:10px;letter-spacing:.16em;text-transform:uppercase;padding:5px 12px;margin-bottom:16px;}
.fn-pill-gold{background:rgba(198,161,91,.1);border-color:rgba(198,161,91,.28);color:#C6A15B;}
.fn-photo-pill{position:absolute;top:24px;left:24px;background:#C1121F;color:#fff;font-family:'Oswald',sans-serif;font-size:11px;font-weight:600;letter-spacing:.16em;text-transform:uppercase;padding:7px 16px;clip-path:polygon(6px 0%,100% 0%,calc(100% - 6px) 100%,0% 100%);z-index:2;}
.fn-badge{background:#C1121F;padding:18px 22px;display:inline-block;}
.fn-badge .num{font-family:'Bebas Neue',sans-serif;font-size:52px;line-height:1;color:#fff;}
.fn-badge .lbl{font-family:'Oswald',sans-serif;font-size:10px;letter-spacing:.14em;text-transform:uppercase;color:rgba(255,255,255,.75);margin-top:4px;}
.fn-stat-num{font-family:'Bebas Neue',sans-serif;font-size:clamp(48px,6vw,72px);line-height:1;color:#fff;}
.fn-stat-lbl{font-family:'Oswald',sans-serif;font-size:12px;font-weight:500;letter-spacing:.16em;text-transform:uppercase;color:rgba(255,255,255,.65);margin-top:6px;}
.fn-perk{display:flex;align-items:flex-start;gap:14px;padding:12px 0;border-bottom:1px solid rgba(198,161,91,.1);}
.fn-perk:last-child{border-bottom:none;}
.fn-perk-icon{width:32px;height:32px;flex-shrink:0;background:rgba(198,161,91,.1);border:1px solid rgba(198,161,91,.3);display:flex;align-items:center;justify-content:center;font-size:14px;}
.fn-perk-title{font-family:'Oswald',sans-serif;font-size:14px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:#F5F5F5;display:block;margin-bottom:3px;}
.fn-perk-desc{font-size:13px;color:rgba(245,245,245,.5);}
.fn-coach-card{background:#0B0B0B;overflow:hidden;border:1px solid rgba(245,245,245,.05);transition:transform .3s;}
.fn-coach-card:hover{transform:translateY(-8px);}
.fn-coach-img{width:100%;height:300px;object-fit:cover;filter:grayscale(40%) contrast(1.1);display:block;transition:transform .5s,filter .5s;}
.fn-coach-card:hover .fn-coach-img{transform:scale(1.06);filter:grayscale(0%);}
.fn-coach-overlay{background:linear-gradient(to top,rgba(11,11,11,.95),transparent);padding:20px;}
.fn-coach-name{font-family:'Bebas Neue',sans-serif;font-size:26px;letter-spacing:.04em;color:#F5F5F5;}
.fn-coach-role{font-family:'Oswald',sans-serif;font-size:11px;font-weight:500;letter-spacing:.15em;text-transform:uppercase;color:#C6A15B;margin-top:3px;}
.fn-coach-bio{padding:16px 20px 20px;font-size:13px;color:rgba(245,245,245,.55);line-height:1.7;}
.fn-testi{background:#2B2B2B;padding:28px;border:1px solid rgba(245,245,245,.05);border-bottom:2px solid #C1121F;}
.fn-testi-stars{color:#C6A15B;font-size:13px;letter-spacing:3px;margin-bottom:14px;}
.fn-testi-text{font-size:14px;color:rgba(245,245,245,.72);line-height:1.8;font-style:italic;margin-bottom:20px;}
.fn-testi-author{display:flex;align-items:center;gap:12px;}
.fn-testi-av{width:40px;height:40px;border-radius:50%;background:#C1121F;color:#fff;font-family:'Bebas Neue',sans-serif;font-size:18px;display:flex;align-items:center;justify-content:center;flex-shrink:0;}
.fn-testi-name{font-family:'Oswald',sans-serif;font-size:14px;font-weight:600;text-transform:uppercase;letter-spacing:.06em;color:#F5F5F5;}
.fn-testi-detail{font-size:11px;color:rgba(245,245,245,.38);}
.fn-foot-social{display:flex;gap:10px;margin-top:16px;}
.fn-foot-social a{width:36px;height:36px;background:rgba(245,245,245,.05);border:1px solid rgba(245,245,245,.1);display:flex;align-items:center;justify-content:center;font-size:16px;color:rgba(245,245,245,.45);transition:all .2s;}
.fn-foot-social a:hover{background:#C1121F;border-color:#C1121F;color:#fff;}
.fn-foot-links{list-style:none;}
.fn-foot-links li{margin-bottom:10px;}
.fn-foot-links a{font-size:13px;color:rgba(245,245,245,.4);transition:color .2s;}
.fn-foot-links a:hover{color:#F5F5F5;}
.fn-foot-h{font-family:'Oswald',sans-serif;font-size:12px;font-weight:600;letter-spacing:.16em;text-transform:uppercase;color:#C6A15B;margin-bottom:16px;}
