e":"spacer"},{"id":"096f581","elType":"widget","settings":{"editor":"<p><span style="font-weight: 400;">Welcome to </span><b>Fighters Boxing Gym</b><span style="font-weight: 400;">, Nashville’s best boxing facility.</span></p><p><span style="font-weight: 400;">We’re not just another fitness club with a few heavy bags in the corner — this is a real boxing gym built for real boxers.</span></p><p><span style="font-weight: 400;">Our programs are designed for </span><b>all levels</b><span style="font-weight: 400;"> — from total beginners to seasoned fighters — with options for </span><b>group classes, youth classes, private sessions, open gym, and sparring</b><span style="font-weight: 400;">. We’ve created an environment where everyone’s welcome to learn the classic art of boxing, get fit, and have fun doing it.</span></p><p><span style="font-weight: 400;">We believe boxing isn’t just a workout. It’s therapy, it’s discipline, it’s empowerment. It teaches you how to breathe under pressure, stay sharp when tired, and fight back when life hits hard. That’s why we’ve dropped every barrier to entry — no experience needed, no ego allowed. Just show up, put in the work, and discover what you’re capable of.</span></p><p><span style="font-weight: 400;">So, what are you fighting for?</span></p><p><span style="font-weight: 400;">Come find out inside Nashville’s best boxing gym — </span><b>Fighters Boxing Gym</b><span style="font-weight: 400;"> — where every round counts and everyone has a reason to fight.</span></p>","audio_effects":[{"_id":"b368dd3"}],"_element_width":"inherit","_element_custom_width":{"unit":"px","size":380,"sizes":[]},"_element_custom_width_tablet":{"unit":"px","size":350,"sizes":[]},"_element_custom_width_mobile":{"unit":"%","size":100,"sizes":[]},"typography_typography":"custom","typography_font_size":{"unit":"px","size":16,"sizes":[]},"parallax":"parallax","parallax_flow":"entrance","parallax_range_start":{"unit":"px","size":15,"sizes":[]},"parallax_y_start":